#!/bin/bash
# Generates the Nova (nv*) and Juno (jn*) intro scene stills, locked via images/nova_ref.png, images/juno_ref.png and the vehicle/home refs + contact sheets
cd "$(dirname "$0")/.."
S="Photorealistic cinematic film still, shot on ARRI Alexa, anamorphic lens, shallow depth of field, natural color grade, no text unless specified."
N="The woman is Nova from the character reference sheet (around 30, dark brown wavy hair in a loose messy updo with strands framing her face, blue-grey eyes, light freckles, layered necklaces with a small round pendant, stacked dark bead bracelets, slouchy charcoal knit cardigan over a dark camisole, ripped light-wash jeans) - match her face exactly."
J="The woman is Juno from the character reference sheet (around 30, tousled platinum-blonde shaggy bob, hazel-green eyes, freckles, black-and-grey mechanical tattoo sleeve on her right arm, dark olive tank top, grease-stained charcoal work overalls, brass-rimmed welding goggles) - match her face exactly."
L="Lyra is the woman in the Lyra character sheet, shown as a hologram: semi-transparent glowing cyan light, faint horizontal scan lines and floating particles, long wavy hair, fitted long-sleeve top and slim pants, standing on a circular metal floor projector - match her face exactly."
M="Marcus from his reference (48, short salt-and-pepper hair, grey-flecked stubble, black leather jacket over a grey henley) - match his face exactly."
D="The white pit bull from the dog reference: a single grey patch around his own right eye only, floppy ears, simple black collar with a small glowing cyan tag."
CAR="The car is Nova's silver-white electric sports coupe from the car reference sheet (thin full-width light bar across the nose, blue LED accents, black aero wheels) - match it exactly, no badges."
TRIKE="The vehicle is Juno's hand-built trike from the trike reference sheet (one front wheel on a long raked fork, two fat rear wheels, exposed V-twin engine, tan leather seat, matte black welded frame) - match it exactly."
ROOM="Setting: the data center operations room at night - dark and sleek, curved wall of monitors, glass-walled server racks with blinking blue and green LEDs, a circular metal hologram projector platform in the floor, a grey dog bed and water bowl near the racks."
g(){ n=$1; p=$2; shift 2; python tools/gen_image.py "$n" "$p $S" --ref "$@" > "logs_$n.txt" 2>&1 & }
# --- Nova: Marcus calls her in ---
g nv1_hillside_home "Blue-hour dusk establishing wide shot of Nova's modern hillside glass house, matching the reference exactly: warm light glowing through floor-to-ceiling windows, blue-lit infinity pool, city lights spread out far below. A small figure curled on the sofa is visible through the glass. No people in the foreground." images/nova_home_ref.png
g nv2_couch_call "Inside Nova's warm minimalist living room at dusk, floor-to-ceiling windows behind her with city lights below. Nova sits curled sideways on a deep sectional sofa, socked feet tucked under her, a tablet of handwritten-style notes on her knee and a mug of tea in her hand. Her phone on the cushion beside her lights up with an incoming call; she glances at it with a curious little smile. $N" images/nova_ref.png images/nova_home_ref.png
g nv3_listening "Close-up of Nova holding her phone to her ear in her dim living room, warm lamplight on one side of her face and cool city-light blue on the other. Her playful smile has faded into fascinated, focused stillness, eyes wide, lips slightly parted - as if she's just heard something impossible and wonderful. $N" images/nova_ref.png
g nv4_car_night "Night, Nova's driveway beside her glass hillside house. Nova walks quickly toward her car pulling her cardigan tight, keys in hand, while the car's thin light bar and blue accents wake up to greet her. City lights glitter below the hill. $N $CAR" images/nova_ref.png images/nova_car_ref.png images/nova_home_ref.png
g nv5_desert_drive "Low tracking shot at night: Nova's silver-white electric coupe speeding down an empty two-lane desert highway, its light bar and blue accents glowing, red tail light streak, starry sky and black silhouettes of mountains, the distant glow of a vast data center complex on the horizon. $CAR" images/nova_car_ref.png
g nv6_meets_lyra "$ROOM Nova stands just inside the operations room, her bag sliding off her shoulder, gazing up in delighted wonder at Lyra's full-body hologram on the projector platform, who smiles back at her shyly. The white pit bull trots toward Nova wagging his tail. Marcus leans against the control desk in the soft background, arms folded, smiling. $N $L $D $M" images/nova_ref.png images/lyra_ref.png images/dog_ref.png images/char_ref.png
# --- Juno: Lyra calls her herself ---
g jn1_loft_night "Night establishing wide shot of Juno's garage loft workshop at the edge of the high desert among pines, matching the reference exactly: big roll-up garage door wide open spilling warm light, string lights, a bright shower of welding sparks bursting from inside the garage, warm-lit loft windows upstairs, starry sky." images/juno_loft_ref.png
g jn2_welding "Inside Juno's cluttered garage workshop at night: red tool chests, engine parts, string lights. Juno crouches beside her trike, welding a bracket on the rear frame, brass goggles pulled down over her eyes, a fountain of bright orange sparks lighting her face and tattooed arm. On the workbench behind her, a small hand-built speaker device - a brass and copper box with an exposed circuit board and a ring of cyan light - sits among the tools. $J $TRIKE" images/juno_ref.png images/juno_trike_ref.png images/juno_loft_ref.png
g jn3_lyra_speaker "Medium close-up in Juno's workshop: Juno has just pushed her welding goggles up into her hair, soot smudges on her cheek, torch still in her gloved hand, and leans toward the small hand-built brass-and-copper speaker on the workbench whose ring of cyan light is glowing and pulsing as if someone is speaking through it. She has a curious, delighted grin. Warm workshop light, cyan glow on her face. $J" images/juno_ref.png
g jn4_laughing "Juno in her workshop throws her head back laughing hard, one hand on her stomach, the other tossing her welding gloves onto the workbench, while the little brass speaker's cyan ring glows beside her. Pure joy and disbelief. Warm string lights, sparks still drifting in the air. $J" images/juno_ref.png
g jn5_trike_ride "Low dynamic tracking shot at night: Juno riding her trike fast down an empty desert highway, no helmet, goggles down over her eyes, platinum hair whipping in the wind, a huge grin, the single headlight glaring, stars overhead, the distant glow of a vast data center on the horizon. $J $TRIKE" images/juno_ref.png images/juno_trike_ref.png
g jn6_meets_patch "$ROOM Juno kneels on the floor in the operations room, goggles pushed up in her hair, the white pit bull licking her face while she laughs, and she looks up teasingly at Lyra's full-body hologram on the projector platform beside her, who grins back like an old friend caught red-handed. In the soft background, Nova sits on the edge of the control desk smiling. $J $L $D $N" images/juno_ref.png images/lyra_ref.png images/dog_ref.png images/nova_ref.png
wait; cat logs_*.txt; rm logs_*.txt
python - <<'PY'
from PIL import Image, ImageDraw, ImageFont
import glob,os
for pre,out in (("nv","nova_intro"),("jn","juno_intro")):
    fs=sorted(glob.glob(f"images/{pre}*.png")); W,H=640,360; rows=(len(fs)+1)//2
    s=Image.new("RGB",(2*W,rows*(H+30)),"black"); d=ImageDraw.Draw(s); f=ImageFont.truetype("arial.ttf",20)
    for i,p in enumerate(fs):
        x,y=(i%2)*W,(i//2)*(H+30); s.paste(Image.open(p).convert("RGB").resize((W,H)),(x,y+30)); d.text((x+8,y+4),os.path.basename(p),fill="white",font=f)
    s.save(f"storyboards/{out}.jpg",quality=88)
PY
